drop function if exists public.get_business_product_access(uuid); create function public.get_business_product_access(p_business_id uuid) returns table(business_id uuid,plan text,location_count integer,location_limit integer,enterprise_enabled boolean,fleet_enabled boolean,is_admin boolean) language sql security definer set search_path=public as $$ with b as (select x.id,x.business_tier::text tier from public.businesses x where x.id=p_business_id), lc as (select count(*)::integer n from public.locations l where l.business_id=p_business_id and coalesce(l.is_active,true)), membership as (select exists(select 1 from public.app_business_memberships m where m.business_id=p_business_id and m.user_id=auth.uid()) member), admin as (select exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin') a) select b.id,coalesce(b.tier,'standard'),lc.n,case when coalesce(b.tier,'standard')='growth' then 5 else null end,(coalesce(b.tier,'standard') in ('growth','enterprise')) or admin.a,exists(select 1 from public.account_service_entitlements e where e.account_user_id=auth.uid() and e.fleet_enabled),admin.a from b,lc,membership,admin where membership.member or admin.a; $$; create or replace function public.enforce_growth_location_cap() returns trigger language plpgsql security definer set search_path=public as $$ declare v_plan text; v_count integer; begin select coalesce(b.business_tier::text,'standard') into v_plan from public.businesses b where b.id=coalesce(new.business_id,old.business_id); if v_plan='growth' then select count(*) into v_count from public.locations l where l.business_id=coalesce(new.business_id,old.business_id) and coalesce(l.is_active,true) and l.id<>coalesce(new.id,old.id); if v_count>=5 and tg_op='INSERT' and coalesce(new.is_active,true) then raise exception 'Business Growth is limited to 5 active locations'; end if; end if; return new; end; $$; drop trigger if exists trg_growth_location_cap on public.locations; create trigger trg_growth_location_cap before insert or update on public.locations for each row execute function public.enforce_growth_location_cap();
